// @flow
import axios from 'axios'
import assert from 'assert'
import PktLineReader from '../utils/pkt-line-reader'

export default class GitRemoteHTTP {
  /*::
  GIT_URL : string
  refs : Map<string, string>
  capabilities : Set<string>
  */
  constructor (url /*: string */) {
    // Auto-append the (necessary) .git if it's missing.
    if (!url.endsWith('.git')) url = url += '.git'
    this.GIT_URL = url
  }
  async discover () {
    this.capabilities = new Set()
    this.refs = new Map()
    let res = await axios.get(
      `${this.GIT_URL}/info/refs?service=git-upload-pack`
    )
    console.log(res.data)
    // There is probably a better way to do this, but for now
    // let's just throw the result parser inline here.
    let read = new PktLineReader(res.data)
    assert(read().toString('utf8') === '# service=git-upload-pack\n')
    let lineTwo = read()
    while (lineTwo === null) lineTwo = read()
    let [firstRef, capabilities] = lineTwo
      .toString('utf8')
      .trim()
      .split('\0')
    console.log(firstRef)
    console.log(capabilities)
    capabilities.split(' ').map(x => this.capabilities.add(x))
    console.log('this.capabilities =', this.capabilities)
    let [ref, name] = firstRef.split(' ')
    this.refs.set(name, ref)
    while (true) {
      let line = read()
      if (line === true) break
      if (line !== null) {
        let [ref, name] = line
          .toString('utf8')
          .trim()
          .split(' ')
        this.refs.set(name, ref)
      }
    }
  }
}

// @flow
// This is modeled after the lockfile strategy used by the git source code.
import pify from 'pify'
import fs from 'fs'
import sleep from './sleep'
const delayedReleases = new Map()

const mkdir = pify(fs.mkdir)
const rmdir = pify(fs.rmdir)

export async function lock (
  filename /*: string */,
  triesLeft /*: number */ = 3
) {
  // check to see if we still have it
  if (delayedReleases.has(filename)) {
    clearTimeout(delayedReleases.get(filename))
    delayedReleases.delete(filename)
    return
  }
  if (triesLeft === 0) {
    throw new Error(
      `Unable to acquire lockfile '${filename}'. Exhausted tries.`
    )
  }
  try {
    await mkdir(`${filename}.lock`)
  } catch (err) {
    if (err.code === 'EEXIST') {
      console.log(`Unable to acquire lockfile. (${triesLeft} tries left)`)
      await sleep(100)
      await lock(filename, triesLeft - 1)
    }
  }
}

export async function unlock (
  filename /*: string */,
  delayRelease /*: number */ = 50
) {
  if (delayedReleases.has(filename)) {
    throw new Error('Cannot double-release lockfile')
  }
  // Basically, we lie and say it was deleted ASAP.
  // But really we wait a bit to see if you want to acquire it again.
  delayedReleases.set(
    filename,
    setTimeout(async () => {
      delayedReleases.delete(filename)
      await rmdir(`${filename}.lock`)
    })
  )
}

import fs from 'fs'
// An async readFile variant that returns null instead of throwing errors
export default async function read (file, options) {
  return new Promise(function (resolve, reject) {
    fs.readFile(
      file,
      options,
      (err, file) => (err ? resolve(null) : resolve(file))
    )
  })
}

// @flow
import BufferCursor from 'buffercursor'

// Technically, this happens to be a pull-stream compatible source.
export default function reader (buffer /*: Buffer */) {
  let buffercursor = new BufferCursor(buffer)
  return function read () {
    if (buffercursor.eof()) return true
    let length = parseInt(buffercursor.slice(4).toString('utf8'), 16)
    console.log('length =', length)
    if (length === 0) return null
    return buffercursor.slice(length - 4).buffer
  }
}

import GitCommit from '../models/GitCommit'
import GitObjectManager from '../managers/GitObjectManager'
import resolveRef from '../utils/resolveRef'
import { HKP } from 'openpgp'
const HttpKeyServer = new HKP()

export default async function verify ({ gitdir, ref, publicKeys }) {
  const oid = await resolveRef({ gitdir, ref })
  const { type, object } = await GitObjectManager.read({ gitdir, oid })
  if (type !== 'commit') {
    throw new Error(
      `git.verify() was expecting a ref type 'commit' but got type '${type}'`
    )
  }
  let commit = GitCommit.from(object)
  let author = commit.headers().author
  let keys = await commit.listSigningKeys()
  if (!publicKeys) {
    let keyArray = await Promise.all(
      keys.map(id => HttpKeyServer.lookup({ keyId: id }))
    )
    publicKeys = keyArray.join('\n')
  }
  let validity = await commit.verify(publicKeys)
  if (!validity) return false
  return { author, keys }
}

// @flow
import { Buffer } from 'buffer'

/*::
type TreeEntry = {
  mode: string,
  path: string,
  oid: string,
  type?: string
}
*/

function parseBuffer (buffer) /*: Array<TreeEntry> */ {
  let _entries = []
  let cursor = 0
  while (cursor < buffer.length) {
    let space = buffer.indexOf(32, cursor)
    if (space === -1) {
      throw new Error(
        `GitTree: Error parsing buffer at byte location ${cursor}: Could not find the next space character.`
      )
    }
    let nullchar = buffer.indexOf(0, cursor)
    if (nullchar === -1) {
      throw new Error(
        `GitTree: Error parsing buffer at byte location ${cursor}: Could not find the next null character.`
      )
    }
    let mode = buffer.slice(cursor, space).toString('utf8')
    if (mode === '40000') mode = '040000' // makes it line up neater in printed output
    let path = buffer.slice(space + 1, nullchar).toString('utf8')
    let oid = buffer.slice(nullchar + 1, nullchar + 21).toString('hex')
    cursor = nullchar + 21
    _entries.push({ mode, path, oid })
  }
  return _entries
}

function nudgeIntoShape (entry) {
  if (!entry.oid && entry.sha) {
    entry.oid = entry.sha // Github
  }
  if (typeof entry.mode === 'number') {
    entry.mode = entry.mode.toString(8) // index
  }
  if (!entry.type) {
    entry.type = 'blob' // index
  }
  return entry
}

export default class GitTree {
  /*::
  _entries: Array<TreeEntry>
  */
  constructor (entries /*: any */) {
    if (Buffer.isBuffer(entries)) {
      this._entries = parseBuffer(entries)
    } else if (Array.isArray(entries)) {
      this._entries = entries.map(nudgeIntoShape)
    } else {
      throw new Error('invalid type passed to GitTree constructor')
    }
  }
  static from (tree) {
    return new GitTree(tree)
  }
  render () {
    return this._entries
      .map(entry => `${entry.mode} ${entry.type} ${entry.oid}    ${entry.path}`)
      .join('\n')
  }
  toObject () {
    return Buffer.concat(
      this._entries.map(entry => {
        let mode = Buffer.from(entry.mode.replace(/^0/, ''))
        let space = Buffer.from(' ')
        let path = Buffer.from(entry.path, { encoding: 'utf8' })
        let nullchar = Buffer.from([0])
        let oid = Buffer.from(entry.oid.match(/../g).map(n => parseInt(n, 16)))
        return Buffer.concat([mode, space, path, nullchar, oid])
      })
    )
  }
  entries () {
    return this._entries
  }
  * [Symbol.iterator] () {
    for (let entry of this._entries) {
      yield entry
    }
  }
}

// @flow
import path from 'path'

/*::
type Node = {
  type: string,
  fullpath: string,
  basename: string,
  metadata: Object, // mode, oid
  parent?: Node,
  children: Array<Node>
}
*/

export default function flatFileListToDirectoryStructure (
  files /*: Array<{path: string}> */
) /*: Node|void */ {
  const inodes /*: Map<string, Node> */ = new Map()
  const mkdir = function (name) /*: Node|void */ {
    if (!inodes.has(name)) {
      let dir /*: Node */ = {
        type: 'tree',
        fullpath: name,
        basename: path.posix.basename(name),
        metadata: {},
        children: []
      }
      inodes.set(name, dir)
      // This recursively generates any missing parent folders.
      // We do it after we've added the inode to the set so that
      // we don't recurse infinitely trying to create the root '.' dirname.
      dir.parent = mkdir(path.posix.dirname(name))
      if (dir.parent && dir.parent !== dir) dir.parent.children.push(dir)
    }
    return inodes.get(name)
  }

  const mkfile = function (name, metadata) /*: Node|void */ {
    if (!inodes.has(name)) {
      let file /*: Node */ = {
        type: 'blob',
        fullpath: name,
        basename: path.posix.basename(name),
        metadata: metadata,
        // This recursively generates any missing parent folders.
        parent: mkdir(path.posix.dirname(name)),
        children: []
      }
      if (file.parent) file.parent.children.push(file)
      inodes.set(name, file)
    }
    return inodes.get(name)
  }

  for (let file of files) {
    mkfile(file.path, file)
  }
  return inodes.get('.')
}

import test from 'ava'
import fs from 'fs'
import {tmpdir, exists} from './_helpers.js'
import {lock, unlock} from '../lib/utils/lockfile'
import sleep from '../lib/utils/sleep'

test('make lockfile', async t => {
  let dir = await tmpdir()
  await lock(dir)
  t.true(exists(`${dir}.lock`))
})

test('cannot double-acquire lockfile', async t => {
  let dir = await tmpdir()
  await lock(dir)
  t.true(exists(`${dir}.lock`))
  try {
    await lock(dir)
    t.fail('Double-acquired lock')
  } catch (err) {
    t.pass()
  }
})

test('can release lockfile', async t => {
  let dir = await tmpdir()
  await lock(dir)
  t.true(exists(`${dir}.lock`))
  await unlock(dir)
  await lock(dir)
  t.true(exists(`${dir}.lock`))
  await unlock(dir)
  await sleep(100)
  t.false(exists(`${dir}.lock`))
})

test('cannot double-release lockfile', async t => {
  let dir = await tmpdir()
  await lock(dir)
  t.true(exists(`${dir}.lock`))
  await unlock(dir)
  try {
    await unlock(dir)
    t.fail('Was able to double-release lockfile')
  } catch (err) {
    t.pass()
  }
})

test('can retry until acquire lockfile', async t => {
  let dir = await tmpdir()
  await lock(dir)
  t.true(exists(`${dir}.lock`))
  setTimeout(() => fs.rmdir(`${dir}.lock`), 100)
  try {
    await lock(dir)
    t.pass()
  } catch (err) {
    t.fail('Could not acquire lock even after lockfile deleted.')
  }
})

// We're implementing a non-standard clone based on the Github API first, because of CORS.
// And because we already have the code.
import axios from 'axios'
import parseLinkHeader from 'parse-link-header'
import GitObjectManager from '../managers/GitObjectManager'
import GitCommit from '../models/GitCommit'
import GitTree from '../models/GitTree'
import write from '../utils/write'
import resolveRef from '../utils/resolveRef'

async function request ({ url, token, headers }) {
  let res = await axios.get(url, {
    headers: {
      Accept: 'application/vnd.github.v3+json',
      Authorization: 'token ' + token,
      ...headers
    }
  })
  return res.data
}

async function fetchRemoteBranches ({ gitdir, remote, user, repo, token }) {
  return request({
    token,
    url: `https://api.github.com/repos/${user}/${repo}/branches`
  }).then(json =>
    Promise.all(
      json.map(branch =>
        write(
          `${gitdir}/refs/remotes/${remote}/${branch.name}`,
          branch.commit.sha + '\n',
          { encoding: 'utf8' }
        )
      )
    )
  )
}

async function fetchTags ({ gitdir, user, repo, token }) {
  return request({
    token,
    url: `https://api.github.com/repos/${user}/${repo}/tags`
  }).then(json =>
    Promise.all(
      json.map(tag =>
        // Curiously, tags are not separated between remotes like branches
        write(`${gitdir}/refs/tags/${tag.name}`, tag.commit.sha + '\n', {
          encoding: 'utf8'
        })
      )
    )
  )
}

async function fetchCommits ({ gitdir, url, user, repo, ref, since, token }) {
  if (!url) {
    url = `https://api.github.com/repos/${user}/${repo}/commits?`
    if (ref) url += `&sha=${ref}`
    if (since) {
      let date = new Date(since * 1000).toISOString()
      url += `&since=${date}`
    }
  }
  let res = await axios.get(url, {
    headers: {
      Accept: 'application/vnd.github.cryptographer-preview',
      Authorization: 'token ' + token
    }
  })
  let json = res.data
  let link = parseLinkHeader(res.headers['link'])

  for (let commit of json) {
    if (!commit.commit.verification.payload) {
      console.log(
        `Commit ${commit.sha} skipped. Due to a technical limitations and my laziness, only signed commits can be cloned from Github over the API`
      )
      continue
    }
    let comm = GitCommit.fromPayloadSignature({
      payload: commit.commit.verification.payload,
      signature: commit.commit.verification.signature
    })
    console.log('Created commit', comm)
    let oid = await GitObjectManager.write({
      gitdir,
      type: 'commit',
      object: comm.toObject()
    })
    if (commit.sha !== oid) {
      console.log("AHOY! MATEY! THAR BE TROUBLE WITH 'EM HASHES!")
    }
    console.log(`Stored commit ${commit.sha}`)
  }

  if (link && link.next) {
    return fetchCommits({
      gitdir,
      user,
      repo,
      ref,
      since,
      token,
      url: link.next.url
    })
  }
}

async function fetchTree ({ gitdir, url, user, repo, sha, since, token }) {
  let json = await request({
    token,
    url: `https://api.github.com/repos/${user}/${repo}/git/trees/${sha}`
  })
  let tree = new GitTree(json.tree)
  let oid = await GitObjectManager.write({
    gitdir,
    type: 'tree',
    object: tree.toObject()
  })
  if (sha !== oid) {
    console.log("AHOY! MATEY! THAR BE TROUBLE WITH 'EM HASHES!")
  }
  console.log(tree.render())
  return Promise.all(
    json.tree.map(async entry => {
      if (entry.type === 'blob') {
        await fetchBlob({
          gitdir,
          url,
          user,
          repo,
          sha: entry.sha,
          since,
          token
        })
      } else if (entry.type === 'tree') {
        await fetchTree({
          gitdir,
          url,
          user,
          repo,
          sha: entry.sha,
          since,
          token
        })
      }
    })
  )
}

async function fetchBlob ({ gitdir, url, user, repo, sha, since, token }) {
  let res = await axios.get(
    `https://api.github.com/repos/${user}/${repo}/git/blobs/${sha}`,
    {
      headers: {
        Accept: 'application/vnd.github.raw',
        Authorization: 'token ' + token
      },
      responseType: 'arraybuffer'
    }
  )
  let oid = await GitObjectManager.write({
    gitdir,
    type: 'blob',
    object: res.data
  })
  if (sha !== oid) {
    console.log("AHOY! MATEY! THAR BE TROUBLE WITH 'EM HASHES!")
  }
}

export default async function fetch ({
  gitdir,
  token,
  user,
  repo,
  ref,
  remote,
  since
}) {
  let json

  if (!ref) {
    console.log('Determining the default branch')
    json = await request({
      token,
      url: `https://api.github.com/repos/${user}/${repo}`
    })
    ref = json.default_branch
  }

  console.log('Receiving branches list')
  let getBranches = fetchRemoteBranches({ gitdir, remote, user, repo, token })

  console.log('Receiving tags list')
  let getTags = fetchTags({ gitdir, user, repo, token })

  console.log('Receiving commits')
  let getCommits = fetchCommits({ gitdir, user, repo, token, ref })

  await Promise.all([getBranches, getTags, getCommits])

  // This is all crap to get a tree SHA from a commit SHA. Seriously.
  let oid = await resolveRef({ gitdir, ref: `${remote}/${ref}` })
  let { type, object } = await GitObjectManager.read({ gitdir, oid })
  if (type !== 'commit') throw new Error(`Unexpected type: ${type}`)
  let comm = GitCommit.from(object.toString('utf8'))
  let sha = comm.headers().tree
  console.log('tree: ', sha)

  await fetchTree({ gitdir, user, repo, token, sha })
}

{
  "name": "esgit",
  "version": "0.0.0",
  "lockfileVersion": 1,
  "requires": true,
  "dependencies": {
